describe('Reading Order - Visual Order Match', () => {
  beforeEach(() => {
    cy.visit('/page');
  });

  it('should display page content in visual reading order', () => {
    // Verify the first element is visible and in the expected position
    cy.get('[data-testid="header"]').should('be.visible');
    cy.get('[data-testid="header"]').should('have.css', 'top', '0px');

    // Verify the second element appears after the first
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="main-content"]').should('have.css', 'top', '60px');

    // Verify the third element appears after the second
    cy.get('[data-testid="sidebar"]').should('be.visible');
    cy.get('[data-testid="sidebar"]').should('have.css', 'top', '100px');

    // Verify the fourth element appears after the third
    cy.get('[data-testid="footer"]').should('be.visible');
    cy.get('[data-testid="footer"]').should('have.css', 'top', '500px');

    // Verify the elements are in the correct sequence
    cy.get('[data-testid="header"]').should('be.first');
    cy.get('[data-testid="main-content"]').should('have.next', '[data-testid="sidebar"]');
    cy.get('[data-testid="sidebar"]').should('have.next', '[data-testid="footer"]');
  });

  it('should handle complex layouts with correct reading order', () => {
    // Verify the main content is visible
    cy.get('[data-testid="main-content"]').should('be.visible');

    // Verify the sidebar is visible and appears after main content
    cy.get('[data-testid="sidebar"]').should('be.visible');
    cy.get('[data-testid="sidebar"]').should('have.css', 'top', '100px');

    // Verify the footer is visible and appears after sidebar
    cy.get('[data-testid="footer"]').should('be.visible');
    cy.get('[data-testid="footer"]').should('have.css', 'top', '550px');

    // Verify the navigation menu is visible and appears before main content
    cy.get('[data-testid="nav-menu"]').should('be.visible');
    cy.get('[data-testid="nav-menu"]').should('have.css', 'top', '0px');

    // Verify the navigation menu is the first element
    cy.get('[data-testid="nav-menu"]').should('be.first');

    // Verify the main content is the second element
    cy.get('[data-testid="main-content"]').should('have.next', '[data-testid="sidebar"]');

    // Verify the sidebar is the third element
    cy.get('[data-testid="sidebar"]').should('have.next', '[data-testid="footer"]');
  });
});
